import pytest

from your_module import safe_divide  # replace "your_module" with the actual module name


@pytest.mark.parametrize(
    "a, b, expected",
    [
        (6.0, 3.0, 2.0),
        (5.0, 2.0, 2.5),
        (-6.0, 3.0, -2.0),
        (6.0, -3.0, -2.0),
        (-6.0, -3.0, 2.0),
        (0.0, 5.0, 0.0),
    ],
)
def test_safe_divide_happy_path(a, b, expected):
    assert safe_divide(a, b) == expected


def test_safe_divide_returns_approximate_float_result():
    assert safe_divide(1.0, 3.0) == pytest.approx(0.3333333333333333)


@pytest.mark.parametrize("denominator", [0, 0.0, -0.0])
def test_safe_divide_by_zero_returns_default_value(denominator):
    assert safe_divide(10.0, denominator) == 0.0


def test_safe_divide_by_zero_returns_custom_default_value():
    assert safe_divide(10.0, 0.0, default=-1.0) == -1.0


def test_safe_divide_zero_by_zero_returns_default_value():
    assert safe_divide(0.0, 0.0) == 0.0


def test_safe_divide_zero_by_zero_returns_custom_default_value():
    assert safe_divide(0.0, 0.0, default=999.0) == 999.0


@pytest.mark.parametrize(
    "a, b",
    [
        ("10", 2.0),
        (10.0, "2"),
        (None, 2.0),
        (10.0, None),
        ([10], 2.0),
        (10.0, [2]),
    ],
)
